import {clone,empty,types,sampleFields,sampleBook,inputFromBook,validateFields,examine,rulesText,canAccess,groupExams,seed} from './engine.js';
import {download,readWorkbook,workbookBlob,fieldsFromBook,referenceSheets,createBA} from './files.js';
const $=s=>document.querySelector(s),KEY='pemeriksaan-prototype-v3';
let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed();}catch{db=seed();}
let uid=sessionStorage.getItem('demo-user')??'rina',ui={},draft=null,setup=null,dialogAction=null,timer=null,progress=0,runStart=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M4 3h13a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3V3z M4 17h16 M8 7h8 M8 11h5',check:'m5 12 4 4L19 6',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h8',copy:'M8 8h13v13H8z M16 8V3H3v13h5',upload:'M12 16V3 m-5 5 5-5 5 5 M3 16v5h18v-5',download:'M12 3v13 m-5-5 5 5 5-5 M3 16v5h18v-5',arrow:'M5 12h14 m-6-6 6 6-6 6',back:'M19 12H5 m6-6-6 6 6 6',close:'m6 6 12 12 M6 18 18 6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.8 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',share:'M8 12l8-6 M8 12l8 6 M8 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M22 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M22 20a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',edit:'m15 4 5 5 M3 21l5-1L21 7l-5-5L3 15z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',logout:'M9 4H3v16h6 M10 12h11 m-5-5 5 5-5 5',alert:'M12 3 1 21h22z M12 9v5 M12 17v1',eye:'M1 12s4-7 11-7 11 7 11 7-4 7-11 7S1 12 1 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',chevron:'m9 5 7 7-7 7',trash:'M3 6h18 M5 6l1 15h12l1-15 M9 6V3h6v3 M10 10v7 M14 10v7'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const btn=(label,action,arg='',kind='',ico='')=>`<button class="btn ${kind}" ${label.startsWith('<svg')?'aria-label="Tutup"':''} data-action="${action}" data-arg="${esc(arg)}">${ico?icon(ico):''}${label}</button>`;
const link=(label,path,kind='',ico='')=>`<a class="btn ${kind}" href="#${path}">${ico?icon(ico):''}${label}</a>`;
const textBtn=(label,action,arg='')=>`<button class="text-btn" data-action="${action}" data-arg="${esc(arg)}">${label}</button>`;
const pill=(label,color='')=>`<span class="pill ${color}">${label}</span>`;
const user=id=>db.users.find(u=>u.id===id)||{name:'Pengguna',short:'Pengguna'};
const me=()=>user(uid);
const stamp=d=>new Date(d).toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
const time=d=>new Date(d).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
const duration=e=>{const s=Math.max(0,Math.round((new Date(e.end)-new Date(e.start))/1000));return s>=60?`${Math.floor(s/60)} menit ${s%60} detik`:`${s} detik`;};
const shareLabel=e=>({private:'Privat',all:'Semua pengguna',selected:'Pengguna tertentu'})[e.share];
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));return true;}catch{toast('Penyimpanan browser penuh. Data terbaru hanya tersimpan selama sesi ini.');return false;}};
const log=(action,object)=>{db.logs.unshift({actor:uid,action,object,time:new Date().toISOString()});save();};
const toast=m=>{$('#toast').textContent=m;$('#toast').style.display='block';setTimeout(()=>{$('#toast').style.display='none';},4000);};
const go=path=>{if(location.hash==='#'+path)render();else location.hash=path;};
const route=()=>decodeURIComponent(location.hash.slice(1)||'acuan').split('/');
const q=(id,placeholder)=>`<div class="search">${icon('search')}<input aria-label="${placeholder}" data-search="${id}" value="${esc(ui[id]||'')}" placeholder="${placeholder}"></div>`;
const match=(v,id)=>String(v).toLowerCase().includes((ui[id]||'').toLowerCase());
const emptyState=(title,message,action='')=>`<div class="empty">${icon('file')}<h3>${title}</h3><p>${message}</p>${action}</div>`;
const field=(label,content,extra='')=>`<div class="field ${extra}"><label>${label}</label>${content.replace(/<(input|select|textarea)\b/,`<$1 aria-label="${esc(label)}"`)}</div>`;
const input=(name,value='',placeholder='',type='text',extra='')=>`<input name="${name}" type="${type}" value="${esc(value)}" placeholder="${placeholder}" ${extra}>`;
const select=(name,value,options,extra='')=>`<select name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
function table(headers,rows,key){
 const size=Number(ui[key+'Size']||20),total=rows.length,max=Math.max(1,Math.ceil(total/size));ui[key+'Page']=Math.min(ui[key+'Page']||1,max);const page=ui[key+'Page'],start=(page-1)*size;
 return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.slice(start,start+size).join('')||`<tr><td colspan="${headers.length}">${emptyState('Tidak ada data','Coba ubah pencarian atau filter.')}</td></tr>`}</tbody></table></div><div class="pagination"><span>Menampilkan ${total?start+1:0}–${Math.min(start+size,total)} dari ${total}</span><div class="row gap8"><button class="btn small" aria-label="Halaman sebelumnya" data-action="page" data-arg="${key}|-1" ${page<=1?'disabled':''}>‹</button><span class="page-number">${page}</span><button class="btn small" aria-label="Halaman berikutnya" data-action="page" data-arg="${key}|1" ${page>=max?'disabled':''}>›</button>${select(key+'Size',size,[[10,'10 / halaman'],[20,'20 / halaman'],[50,'50 / halaman']],`data-page-size="${key}" aria-label="Jumlah per halaman"`)}</div></div>`;
}
function header(title,subtitle,actions='',crumbs=[]){return `<div class="crumb">${crumbs.map((c,i)=>`${i?'<span class="separator">/</span>':''}${Array.isArray(c)?`<a href="#${c[1]}">${esc(c[0])}</a>`:esc(c)}`).join('')}</div><header class="page-head"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</header>`;}
function shell(content){const section=route()[0];return `<aside class="sidebar"><a class="brand" href="#acuan"><span class="brand-icon">${icon('check')}</span><span><b>PEMERIKSAAN</b><small>DATA MIGRASI</small></span></a><nav><div class="nav-label">RUANG KERJA</div><a class="nav-item ${section==='acuan'?'active':''}" href="#acuan">${icon('book')}Acuan</a><a class="nav-item ${section==='pemeriksaan'?'active':''}" href="#pemeriksaan">${icon('grid')}Pemeriksaan</a>${me().role==='admin'?`<a class="nav-item ${section==='akun'?'active':''}" href="#akun">${icon('users')}Kelola Akun</a>`:''}</nav><div class="sidebar-foot"><div class="demo-tag">PROTOTIPE INTERAKTIF</div><div class="account"><span class="avatar">${me().short.slice(0,2).toUpperCase()}</span><div class="grow"><select aria-label="Ganti pengguna demo" id="demo-user">${db.users.filter(u=>u.active).map(u=>`<option value="${u.id}" ${u.id===uid?'selected':''}>${esc(u.short)}</option>`).join('')}</select><div class="small">${me().role==='admin'?'Administrator':'Pengguna'}</div></div></div><button class="text-btn" data-action="demo-guide">${icon('eye')}Panduan demo</button><button class="text-btn" data-action="logout">${icon('logout')}Keluar</button></div></aside><main class="main" id="main-content">${content}</main>`;}
function render(){
 if(!uid||!me().active){$('#app').innerHTML=loginPage();return;}
 const [section,page,id]=route();let content='';
 if(section==='acuan')content=page==='baru'?createRefPage():page==='editor'?editorPage(id):page==='lihat'?referencePage(id):referencesPage();
 else if(section==='pemeriksaan')content=page==='baru'?newExamPage():page==='hasil'?resultPage(id):page==='data'?dataPage(id):page==='acuan'?examReferencePage(id):page==='bagikan'?sharePage(id):page==='ulang'?repeatPage(id):page==='proses'?processingPage(id):examsPage();
 else if(section==='akun')content=accountsPage();else content=referencesPage();
 $('#app').innerHTML=shell(content);document.title=`${$('#main-content h1')?.textContent||'Pemeriksaan'} · Pemeriksaan Data`;
}
function referencesPage(){const tab=ui.refTab||'published',refs=tab==='draft'?db.drafts.filter(d=>d.owner===uid):db.refs.filter(r=>!db.refs.some(x=>x.family===r.family&&x.version>r.version));const rows=refs.filter(r=>match(`${r.name} ${user(r.owner).name}`,'refSearch')).map(r=>`<tr><td><strong>${esc(r.name||'Acuan tanpa nama')}</strong><span class="sub">${esc(r.description||'')}</span></td><td>${tab==='draft'?pill('Draf','amber'):`${r.version}`}</td><td>${esc(user(r.owner).short)}</td><td>${stamp(tab==='draft'?r.updated:r.published)}</td><td><div class="actions">${tab==='draft'?`<a href="#acuan/editor/${r.id}">Lanjutkan</a>${textBtn('Hapus','delete-draft',r.id)}`:`<a href="#acuan/lihat/${r.id}">Lihat</a>${textBtn('Salin','copy-ref',r.id)}`}</div></td></tr>`);
 return header('Acuan','Kelola field dan aturan yang menjadi dasar pemeriksaan.',link('Buat Acuan','acuan/baru','primary','plus'),[['Acuan','acuan'],'Daftar'])+`<section class="card"><div class="toolbar"><div class="tabs"><button class="tab ${tab==='published'?'active':''}" data-action="ref-tab" data-arg="published">Semua acuan terbit</button><button class="tab ${tab==='draft'?'active':''}" data-action="ref-tab" data-arg="draft">Draf Saya <span class="count">${db.drafts.filter(d=>d.owner===uid).length}</span></button></div>${q('refSearch','Cari nama acuan atau pembuat')}</div>${table(['NAMA ACUAN','VERSI','PEMBUAT',tab==='draft'?'DIUBAH TERAKHIR':'WAKTU TERBIT','AKSI'],rows,'refs')}</section>`;
}
function createRefPage(){return header('Buat Acuan','Pilih cara memulai, lalu lengkapi field dan aturan di editor.',link('Kembali','acuan','','back'),[['Acuan','acuan'],'Buat Acuan'])+`<div class="stack"><div class="methods"><section class="card method"><div class="method-icon">${icon('edit')}</div><h2>Isi manual</h2><p>Susun nama field dan aturan pemeriksaan dari awal.</p><div class="actions">${btn('Mulai dari Kosong','new-ref','','primary','plus')}</div></section><section class="card method"><div class="method-icon">${icon('upload')}</div><h2>Impor Excel</h2><p>Ambil isi template, lalu perbaiki atau lengkapi di editor.</p><div class="actions">${btn('Pilih File XLSX','import-ref','','primary','upload')}${textBtn('Unduh template','template')}</div></section><section class="card method"><div class="method-icon">${icon('copy')}</div><h2>Salin acuan</h2><p>Gunakan acuan terbit sebagai dasar acuan baru.</p><div class="actions">${btn('Pilih Acuan','show-copy','','primary','copy')}</div></section></div><section class="card" id="copy-list"><div class="card-head"><div><h2>Pilih acuan untuk disalin</h2><p>Salinan menjadi draf milik Anda dan dapat diubah sebelum terbit.</p></div>${q('copySearch','Cari acuan')}</div>${table(['NAMA ACUAN','VERSI','PEMBUAT','AKSI'],db.refs.filter(r=>!db.refs.some(x=>x.family===r.family&&x.version>r.version)).filter(r=>match(r.name,'copySearch')).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${r.version}</td><td>${user(r.owner).short}</td><td>${textBtn('Salin acuan','copy-ref',r.id)}</td></tr>`),'copy')}</section></div>`;}
function referenceRows(fields,editable=false){return fields.filter(f=>editable||match(`${f.name} ${rulesText(f)}`,'fieldSearch')).map((f,i)=>`<tr><td><strong>${esc(f.name||'Belum diberi nama')}</strong></td><td>${esc(types[f.type]||f.type)}</td><td>${f.column?'Ya':'Tidak'}</td><td>${({always:'Ya',never:'Tidak',conditional:'Bersyarat'})[f.required]||pill('Perlu diperbaiki','red')}</td><td class="long">${esc(rulesText(f))}</td>${editable?`<td><div class="actions">${textBtn('Ubah','edit-field',i)}${textBtn('Hapus','delete-field',i)}</div></td>`:''}</tr>`);}
function editorPage(id){
 if(!draft||draft.id!==id)draft=clone(db.drafts.find(d=>d.id===id&&d.owner===uid));if(!draft)return unavailable();
 const issues=draft.validated?validateFields(draft.name,draft.fields):null;
 return header('Editor Acuan',draft.source?esc(draft.source):'Tentukan field dan aturan pemeriksaan.',pill('Draf','amber'),[['Acuan','acuan'],'Draf','Editor'])+`<div class="stack"><section class="card"><div class="form-grid">${field('NAMA ACUAN',input('refName',draft.name,'Contoh: Data Aset','text','data-draft="name"'))}${field('DESKRIPSI',input('refDescription',draft.description,'Tujuan penggunaan acuan','text','data-draft="description"'))}</div></section><section class="card"><div class="card-head"><div><h2>Field dan aturan</h2><p>Nama field digunakan untuk mengenali kolom pada file data.</p></div><div class="actions">${btn('Impor ulang','reimport-ref','','','upload')}${btn('Tambah Field','edit-field','new','','plus')}</div></div>${draft.fields.length?table(['FIELD','TIPE DATA','WAJIB KOLOM','WAJIB ISI','ATURAN','AKSI'],referenceRows(draft.fields,true),'editor'):emptyState('Belum ada field','Tambahkan field untuk mulai menyusun acuan.',btn('Tambah Field','edit-field','new','primary','plus'))}</section>${issues?.length?`<div class="notice red"><b>Konfigurasi perlu diperbaiki</b><ul>${issues.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}<section class="card footer-actions"><div>${issues&&!issues.length?`<div class="row">${pill('Validasi berhasil','green')}<span class="muted small">Tinjau sebelum menerbitkan acuan.</span></div>`:`<span class="muted small">${draft.fields.length} field · Belum diterbitkan</span>`}</div><div class="actions">${btn('Simpan Draf','save-draft')}${btn('Validasi','validate-draft')}${btn('Pratinjau & Terbitkan','preview-publish','','primary','arrow')}</div></section></div>`;
}
function referencePage(id){const ref=db.refs.find(r=>r.id===id);if(!ref)return unavailable();const versions=db.refs.filter(r=>r.family===ref.family).sort((a,b)=>b.version-a.version);return header(esc(ref.name),`Versi ${ref.version} · ${ref.fields.length} field · Terbit ${stamp(ref.published)}`,`${btn('Unduh Excel','download-ref',ref.id,'','download')}${btn('Salin Acuan','copy-ref',ref.id,'','copy')}${ref.owner===uid?btn('Ubah Acuan','modify-ref',ref.id,'primary','edit'):''}`,[['Acuan','acuan'],ref.name])+`<div class="stack"><section class="card"><div class="row between wrap"><div><span class="label">PEMBUAT ACUAN</span><h3 class="mt16">${esc(user(ref.owner).name)}</h3><p class="muted small mt16">${esc(ref.description||'')}</p></div><div class="field"><label>VERSI YANG DITAMPILKAN</label>${select('refVersion',ref.id,versions.map(r=>[r.id,`Versi ${r.version} · ${stamp(r.published)}`]),'data-version')}</div></div></section>${referenceTable(ref)}</div>`;}
function referenceTable(ref){return `<section class="card"><div class="card-head"><div><h2>Field dan aturan</h2><p>${ref.fields.length} field dalam acuan</p></div>${q('fieldSearch','Cari field atau aturan')}</div>${table(['FIELD','TIPE DATA','WAJIB KOLOM','WAJIB ISI','ATURAN'],referenceRows(ref.fields),'fields')}</section>`;}
function unavailable(){return header('Halaman tidak tersedia','')+`<section class="card">${emptyState('Data tidak tersedia','Data mungkin tidak ditemukan atau tidak dibagikan kepada Anda.',link('Kembali ke Pemeriksaan','pemeriksaan','primary'))}</section>`;}
function stat(label,value,sub,color='',ico=''){return `<div class="card stat"><div class="label">${label}</div><div class="value-row"><div class="stat-value ${color}">${value}</div>${ico?`<div class="stat-icon">${icon(ico)}</div>`:''}</div><p>${sub}</p></div>`;}
function filteredGroups(){
 let exams=db.exams.filter(e=>canAccess(e,uid));
 if(ui.examTab==='mine')exams=exams.filter(e=>e.owner===uid);
 if(ui.examTab==='shared')exams=exams.filter(e=>e.owner!==uid);
 exams=exams.filter(e=>{
  const hasIssues=e.result.bad>0||e.result.findings.length>0;
  const resultMatches=!ui.examResult||(ui.examResult==='bad'?hasIssues:!hasIssues);
  return (!ui.dateFrom||e.end.slice(0,10)>=ui.dateFrom)&&(!ui.dateTo||e.end.slice(0,10)<=ui.dateTo)&&(!ui.examRef||e.ref.family===ui.examRef)&&resultMatches&&match(`${e.id} ${e.input.name} ${e.ref.name} ${user(e.owner).name}`,'examSearch');
 });
 return groupExams(exams);
}
function examsPage(){const groups=filteredGroups(),bad=groups.filter(g=>g[0].result.bad>0||g[0].result.findings.length>0).length;const tab=ui.examTab||'all';return header('Pemeriksaan','Ringkasan hasil berdasarkan tab dan filter yang dipilih.',link('Pemeriksaan Baru','pemeriksaan/baru','primary','plus'),[['Pemeriksaan','pemeriksaan'],'Daftar'])+`<div class="stack"><section class="card"><div class="toolbar"><div class="tabs">${[['all','Semua'],['mine','Pemeriksaan Saya'],['shared','Dibagikan kepada Saya']].map(([v,l])=>`<button class="tab ${tab===v?'active':''}" data-action="exam-tab" data-arg="${v}">${l}</button>`).join('')}</div>${textBtn('Reset filter','clear-filters')}</div><div class="filters">${field('Tanggal mulai',input('dateFrom',ui.dateFrom,'','date','data-filter="dateFrom"'))}${field('Tanggal akhir',input('dateTo',ui.dateTo,'','date','data-filter="dateTo"'))}${field('Acuan',select('examRef',ui.examRef||'',[['','Semua acuan'],...db.refs.filter((r,i,a)=>a.findIndex(x=>x.family===r.family)===i).map(r=>[r.family,r.name])],'data-filter="examRef"'))}${field('Hasil',select('examResult',ui.examResult||'',[['','Semua hasil'],['bad','Perlu perbaikan'],['good','Tanpa temuan']],'data-filter="examResult"'))}</div><div class="stats three">${stat('PEMERIKSAAN TAMPIL',groups.length,'Input identik dihitung sekali','','file')}${stat('PERLU PERBAIKAN',bad,'Pemeriksaan dengan temuan','bad','alert')}${stat('TANPA TEMUAN',groups.length-bad,'Seluruh aturan terpenuhi','good','check')}</div></section><section class="card"><div class="card-head"><div><h2>Riwayat pemeriksaan</h2><p>Hasil terbaru untuk setiap kombinasi data dan versi acuan.</p></div>${q('examSearch','Cari file, ID, atau pemeriksa')}</div>${table(['PEMERIKSAAN','FILE / ACUAN','PEMERIKSA','HASIL','AKSES','AKSI'],groups.map(g=>{const e=g[0];return `<tr><td><b>${e.id}</b><span class="sub">${stamp(e.end)}</span>${g.length>1?textBtn(`${g.length-1} pemeriksaan terdahulu`,'group-history',e.id):''}</td><td><b class="filename">${esc(e.input.name)}</b><span class="sub">${esc(e.ref.name)} · v${e.ref.version}</span></td><td>${esc(user(e.owner).short)}${e.owner===uid?'<span class="sub">Milik saya</span>':''}</td><td><b class="${e.result.bad?'bad':'good'}">${e.result.bad}/${e.result.total} baris perlu perbaikan</b><span class="sub">${e.result.findings.length} temuan</span></td><td>${pill(shareLabel(e),e.share==='private'?'':'blue')}</td><td><a href="#pemeriksaan/hasil/${e.id}" class="text-btn">Detail ${icon('arrow')}</a></td></tr>`;}),'exams')}</section></div>`;}
function freshSetup(){return {book:null,sheet:'',header:1,refId:db.refs[0]?.id||'',origin:null};}
function newExamPage(){setup??=freshSetup();let inp=null,error='';if(setup.book){try{inp=inputFromBook(setup.book,setup.sheet,Number(setup.header));}catch{error='Pilih sheet dan baris header yang tersedia.';}}
 const ref=db.refs.find(r=>r.id===setup.refId);return header('Pemeriksaan Baru',setup.origin?`Berdasarkan ${setup.origin} · Hasil baru menjadi milik Anda dan bersifat privat.`:'Unggah data, tentukan sheet dan header, lalu pilih acuan.',link('Kembali','pemeriksaan','','back'),[['Pemeriksaan','pemeriksaan'],'Baru'])+`<div class="stack"><section class="card"><div class="step-head"><span class="step">1</span><h2>Unggah file data</h2></div><div class="dropzone"><div class="row"><span class="file-icon">${icon('file')}</span><div><h3>${setup.book?esc(setup.book.name):'Pilih file data yang akan diperiksa'}</h3><p>Excel (.xlsx)${setup.book?` · ${setup.book.sheets.length} sheet`:' · Pilih file dari perangkat Anda'}</p></div></div><div class="actions">${btn(setup.book?'Ganti File':'Pilih File XLSX','import-data','','primary','upload')}${!setup.book?btn('Gunakan Data Contoh','use-sample'):''}</div></div>${!setup.book?`<div class="mt16">${textBtn('Unduh contoh data Excel','download-sample')}</div>`:''}</section>${inp?`<section class="card"><div class="step-head"><span class="step">2</span><h2>Tentukan sheet dan header</h2></div><div class="form-grid mb16">${field('SHEET',select('sheet',setup.sheet,setup.book.sheets.map(s=>[s.name,s.name]),'data-setup="sheet"'))}${field('BARIS HEADER',input('header',setup.header,'','number','min="1" step="1" data-setup="header"'))}</div>${inp.headers.length?`<p class="muted small mb16">${inp.rows.length} baris data · ${inp.headers.length} field</p>${sourceTable(inp,'setupPreview')}`:`<div class="notice amber">Baris header tidak berisi nama kolom. Pilih baris lain.</div>`}</section>`:''}<section class="card"><div class="step-head"><span class="step">${inp?3:2}</span><h2>Pilih acuan terbit</h2></div><div class="row wrap">${field('ACUAN',select('refId',setup.refId,[['','Pilih acuan'],...db.refs.map(r=>[r.id,`${r.name} · versi ${r.version} · ${r.fields.length} field`])],'data-setup="refId"'),'grow')}${ref?btn('Lihat Acuan','setup-ref',ref.id,'','eye'):''}</div><p class="muted small mt16">Nama kolom diperiksa langsung terhadap field pada acuan.</p></section>${error?`<div class="notice red">${error}</div>`:''}<section class="card footer-actions"><span class="muted small">${icon('lock')} Hasil pemeriksaan baru tersimpan sebagai Privat.</span>${btn('Mulai Pemeriksaan','start-exam','','primary','arrow')}</section></div>`;
}
function sourceTable(inp,key){const search=ui[key+'Search']||'';const rows=inp.rows.filter(r=>`${r.row} ${r.values.join(' ')}`.toLowerCase().includes(search.toLowerCase())).map(r=>`<tr><td><b>${r.row}</b></td>${inp.headers.map((_,i)=>`<td>${empty(r.values[i])?'<span class="muted">Kosong</span>':esc(r.values[i])}</td>`).join('')}</tr>`);return table(['BARIS EXCEL',...inp.headers.map(esc)],rows,key);}
function getExam(id){return db.exams.find(e=>e.id===id&&canAccess(e,uid));}
function identityCard(e){return `<section class="card identity"><section><span class="label">DATA YANG DIPERIKSA</span><h3>${esc(e.input.name)}</h3><p>${e.input.rows.length} baris · ${e.input.headers.length} field · Sheet ${esc(e.input.sheet)} · header baris ${e.input.header}</p>${link('Lihat data',`pemeriksaan/data/${e.id}`,'','eye')}</section><section><span class="label">ACUAN YANG DIPAKAI</span><h3>${esc(e.ref.name)}</h3><p>Versi ${e.ref.version} · ${e.ref.fields.length} field · Terbit</p>${link('Lihat acuan',`pemeriksaan/acuan/${e.id}`,'','book')}</section><section><div class="section-top"><span class="label">PEMERIKSAAN</span>${pill('Selesai','green')}</div><h3>${esc(user(e.owner).name)}</h3><p>${new Date(e.end).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})} · ${time(e.start)}–${time(e.end)}</p><p class="duration">${icon('clock')} Durasi ${duration(e)}</p></section></section>`;}
function resultPage(id){const e=getExam(id);if(!e)return unavailable();const r=e.result,percent=r.total?Math.round(r.good/r.total*100):0;const counts={};r.findings.forEach(f=>counts[f.field]=(counts[f.field]||0)+1);const fields=Object.entries(counts).sort((a,b)=>b[1]-a[1]);const fieldPage=ui.chartPage||1,slice=fields.slice((fieldPage-1)*5,fieldPage*5);const findings=r.findings.filter(f=>match(`${f.row} ${f.field} ${f.reason} ${f.value}`,'findingSearch'));return header(`Hasil Pemeriksaan ${esc(e.ref.name)}`,`${e.id} · Hasil berdasarkan versi acuan dan file yang dipilih.`,`${e.owner===uid?link('Bagikan',`pemeriksaan/bagikan/${id}`,'','share'):''}${btn('Generate BA','ba',id)}${btn('Unduh Laporan','report',id,'','download')}${link('Pemeriksaan Baru',`pemeriksaan/ulang/${id}`,'primary','plus')}`,[['Pemeriksaan','pemeriksaan'],e.id,'Hasil'])+`<div class="stack">${identityCard(e)}<div class="stats">${stat('BARIS DIPERIKSA',r.total,r.total?`Baris Excel ${e.input.rows[0].row}–${e.input.rows.at(-1).row}`:'Tidak ada baris')}${stat('PERLU PERBAIKAN',r.bad,`${r.total?Math.round(r.bad/r.total*100):0}% dari ${r.total} baris`,'bad')}${stat('MEMENUHI ATURAN',r.good,`${percent}% dari ${r.total} baris`,'good')}${stat('KELENGKAPAN ISIAN WAJIB',`${r.filled}/${r.required}`,r.required?`${Math.round(r.filled/r.required*100)}% terisi`:'Tidak ada isian wajib','blue')}</div><div class="charts"><section class="card"><h2>Temuan menurut field</h2><p class="muted small mt16">Jumlah temuan aturan pada setiap field</p>${fields.length?`<div class="bars">${slice.map(([name,count])=>`<div class="bar-row"><span>${esc(name)}</span><div class="bar-track"><div class="bar-fill" style="width:${count/Math.max(...fields.map(f=>f[1]))*100}%"></div></div><span class="muted">${count} temuan</span></div>`).join('')}</div>${fields.length>5?`<div class="row end mt16">${btn('‹','chart-page',-1,'small')}${fieldPage}/${Math.ceil(fields.length/5)}${btn('›','chart-page',1,'small')}</div>`:''}`:`<div class="notice green mt24">Seluruh data memenuhi aturan acuan.</div>`}</section><section class="card"><h2>Kondisi baris data</h2><p class="muted small mt16">Dari ${r.total} baris yang diperiksa</p><div class="donut-wrap"><div class="donut" style="background:conic-gradient(var(--green) 0 ${percent}%,var(--red) ${percent}% 100%)"><div class="donut-inner"><b>${r.total}</b><span>baris</span></div></div><div class="legend"><div><span class="dot" style="background:var(--green)"></span><span><b>${r.good}</b> baris memenuhi aturan</span></div><div><span class="dot" style="background:var(--red)"></span><span><b>${r.bad}</b> baris perlu perbaikan</span></div></div></div></section></div><section class="card"><div class="card-head"><div><h2>Detail temuan</h2><p>Nomor baris mengikuti posisi asli pada file Excel.</p></div>${q('findingSearch','Cari nomor baris, field, atau alasan')}</div>${table(['BARIS','FIELD','NILAI FILE','ATURAN / ALASAN'],findings.map(f=>`<tr><td><b>${f.row}</b></td><td>${esc(f.field)}</td><td class="bad strong">${empty(f.value)?'Kosong':esc(f.value)}</td><td>${esc(f.reason)}</td></tr>`),'findings')}${r.pending.length?`<div class="notice mt16"><b>${r.pending.length} kondisi belum dapat dinilai.</b> ${r.pending.length<=2?r.pending.map(p=>`${esc(p.field)} baris ${p.row}, karena ${esc(p.source)} sebagai penentu kosong atau tidak valid.`).join(' '):'Nilai field penentu kosong atau tidak valid.'} ${textBtn('Lihat rincian','pending',id)}</div>`:''}</section>${e.origin?`<div class="muted small">Dibuat berdasarkan pemeriksaan ${esc(e.origin)}.</div>`:''}</div>`;}
function dataPage(id){const e=getExam(id);if(!e)return unavailable();return header('Pratinjau data yang diperiksa',`${esc(e.input.name)} · Sheet ${esc(e.input.sheet)} · header baris ${e.input.header}`,`${btn('Unduh File','download-data',id,'','download')}${link('Kembali ke Hasil',`pemeriksaan/hasil/${id}`,'','back')}`,[['Pemeriksaan','pemeriksaan'],[id,`pemeriksaan/hasil/${id}`],'Data'])+`<section class="card"><div class="card-head"><div><h2>Data sumber</h2><p>${e.input.rows.length} baris data · ${e.input.headers.length} field</p></div>${q('dataSearch','Cari nomor baris atau nilai')}</div>${sourceTable(e.input,'data')}</section>`;}
function examReferencePage(id){const e=getExam(id);if(!e)return unavailable();return header('Pratinjau acuan',`${esc(e.ref.name)} · Versi ${e.ref.version} · ${e.ref.fields.length} field`,link('Kembali ke Hasil',`pemeriksaan/hasil/${id}`,'','back'),[['Pemeriksaan','pemeriksaan'],[id,`pemeriksaan/hasil/${id}`],'Acuan'])+referenceTable(e.ref);}
function sharePage(id){const e=getExam(id);if(!e||e.owner!==uid)return unavailable();const scope=ui.shareScope??e.share;return header('Bagikan Pemeriksaan',`${e.id} · ${esc(e.ref.name)}`,link('Kembali ke Hasil',`pemeriksaan/hasil/${id}`,'','back'),[['Pemeriksaan','pemeriksaan'],[id,`pemeriksaan/hasil/${id}`],'Bagikan'])+`<section class="card"><div class="card-head"><div><h2>Siapa yang dapat mengakses?</h2><p>Pilih akses untuk hasil dan file pada pemeriksaan ini.</p></div>${pill(shareLabel(e),'blue')}</div><form id="share-form" data-id="${id}">${[['private','Privat','Hanya Anda yang dapat mengakses pemeriksaan ini.'],['selected','Pengguna tertentu','Bagikan kepada akun yang Anda pilih.'],['all','Semua pengguna sistem','Seluruh akun aktif dapat mengakses hasil dan file.']].map(([v,l,d])=>`<label class="option"><input type="radio" name="shareScope" value="${v}" ${scope===v?'checked':''}><span><b>${l}</b><p>${d}</p></span></label>`).join('')}<div id="recipient-list" ${scope==='selected'?'':'hidden'}><span class="label">PILIH PENGGUNA</span><div class="user-pick">${db.users.filter(u=>u.active&&u.id!==uid).map(u=>`<label class="check"><input type="checkbox" name="recipient" value="${u.id}" ${e.recipients.includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}</div></div><div class="notice mt24">Penerima dapat melihat hasil, mengunduh file dan laporan, membuat BA, serta memulai pemeriksaan baru. Pengaturan akses tetap dikelola oleh Anda.</div><div class="actions mt24"><button class="btn primary" type="submit">Simpan Pengaturan</button></div></form></section>`;}
function repeatPage(id){const e=getExam(id);if(!e)return unavailable();return header('Pemeriksaan Baru dari Riwayat',`Gunakan ${e.id} sebagai dasar pemeriksaan baru.`,link('Kembali ke Hasil',`pemeriksaan/hasil/${id}`,'','back'),[['Pemeriksaan','pemeriksaan'],[id,`pemeriksaan/hasil/${id}`],'Pemeriksaan Baru'])+`<div class="stack"><section class="card"><h2>Data pemeriksaan asal</h2><dl class="definition mt24"><dt>Pemeriksaan</dt><dd>${e.id} · ${esc(user(e.owner).name)}</dd><dt>File data</dt><dd>${esc(e.input.name)}</dd><dt>Acuan</dt><dd>${esc(e.ref.name)} · versi ${e.ref.version}</dd></dl></section><section class="card"><h2 class="mb16">Apa yang akan digunakan?</h2><form id="repeat-form" data-id="${id}">${[['same','Gunakan data dan acuan yang sama','Jalankan kembali tanpa mengubah input.'],['ref','Ganti acuan','Pertahankan file, sheet, dan baris header.'],['file','Ganti file data','Gunakan acuan yang sama dengan data baru.'],['both','Ganti file dan acuan','Pilih kembali file data dan acuan.']].map(([v,l,d],i)=>`<label class="option"><input type="radio" name="repeatMode" value="${v}" ${i===0?'checked':''}><span><b>${l}</b><p>${d}</p></span></label>`).join('')}<div class="row between wrap mt24"><p class="muted small">Hasil baru milik ${esc(me().short)} · Akses awal Privat</p><button class="btn primary" type="submit">Lanjutkan ${icon('arrow')}</button></div></form></section></div>`;}
function processingPage(id){if(!setup?.running||setup.running.id!==id){const e=getExam(id);return e?resultPage(id):unavailable();}const e=setup.running;return header(`Pemeriksaan ${id}`,'Data sedang diperiksa berdasarkan aturan acuan.',pill('Diproses','blue'),[['Pemeriksaan','pemeriksaan'],id])+`<div class="stack"><section class="card"><div class="form-grid"><div><span class="label">DATA YANG DIPERIKSA</span><h3 class="mt16">${esc(e.input.name)}</h3><p class="muted small mt16">${e.input.rows.length} baris · ${e.input.headers.length} field · Sheet ${esc(e.input.sheet)}</p></div><div><span class="label">ACUAN</span><h3 class="mt16">${esc(e.ref.name)} · versi ${e.ref.version}</h3><p class="muted small mt16">Pemeriksa: ${esc(me().name)}</p></div></div></section><section class="card"><div class="row"><span class="spinner"></span><div><h2>Memeriksa data</h2><p class="muted small mt16" id="elapsed">Waktu berjalan: ${Math.floor((Date.now()-runStart)/1000)} detik</p></div></div><div class="progress-track"><div id="progress-fill" style="width:${progress}%"></div></div><div class="progress-stages"><span class="done">1. Membaca kolom</span><span>2. Memeriksa aturan</span><span>3. Menyiapkan hasil</span></div><div class="notice mt24">Simulasi proses berlangsung beberapa detik. Durasi yang dicatat mengikuti proses prototipe ini.</div></section></div>`;}
function accountsPage(){if(me().role!=='admin')return unavailable();return header('Kelola Akun','Buat akun dan kelola akses masuk pengguna.',btn('Tambah Pengguna','new-account','','primary','plus'),[['Kelola Akun','akun'],'Daftar'])+`<section class="card"><div class="card-head"><h2>Akun pengguna</h2>${q('accountSearch','Cari nama atau username')}</div>${table(['NAMA LENGKAP','USERNAME','PERAN','STATUS','AKSI'],db.users.filter(u=>match(`${u.name} ${u.username}`,'accountSearch')).map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.username)}</td><td>${u.role==='admin'?'Administrator':'Pengguna'}</td><td>${pill(u.active?'Aktif':'Nonaktif',u.active?'green':'')}</td><td><div class="actions">${textBtn('Reset password','reset-password',u.id)}${u.role!=='admin'?textBtn(u.active?'Nonaktifkan':'Aktifkan','toggle-user',u.id):''}</div></td></tr>`),'accounts')}</section>`;}
function loginPage(){return `<div class="login"><section class="login-intro"><div class="row">${icon('check')}<b>PEMERIKSAAN DATA</b></div><h1>Pastikan data siap.<br>Mulai dari acuan.</h1><p>Periksa kelengkapan dan kesesuaian data. Telusuri temuan sampai ke baris sumbernya.</p></section><section class="login-form"><div><span class="label">PROTOTIPE INTERAKTIF</span><h1 class="mt16">Masuk ke ruang kerja</h1><p class="muted mt16">Gunakan akun demo untuk mencoba alur sistem.</p><form id="login-form">${field('USERNAME',input('username','','rina / budi / admin','text','required autocomplete="username"'))}${field('PASSWORD',input('password','','Password demo: demo123','password','required autocomplete="current-password"'))}<button class="btn primary" type="submit">Masuk ${icon('arrow')}</button><p class="muted small">Akun awal: rina, budi, atau admin. Password: demo123.</p></form><div id="login-error" class="inline-error"></div></div></section></div>`;}
function modal(title,subtitle,body,footer='',wide=false){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${btn(icon('close'),'close','','icon')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input,.modal button,.modal select')?.focus(),0);}
function close(){ $('#overlay').innerHTML='';document.body.style.overflow='';dialogAction=null;}
function confirmAction(title,message,action,label='Lanjutkan',danger=false){dialogAction=action;modal(title,'',`<p>${message}</p>`,btn('Batal','close')+btn(label,'confirm','',danger?'danger':'primary'));}
function createDraft(ref=null,modify=false){const d={id:'draft-'+Date.now(),owner:uid,name:ref?modify?ref.name:`${ref.name} — Salinan`:'',description:ref?.description||'',fields:clone(ref?.fields||[]),source:ref?`${modify?'Perubahan':'Salinan'} dari ${ref.name} versi ${ref.version}.`:'',family:modify?ref.family:null,updated:new Date().toISOString(),validated:false};db.drafts.push(d);draft=clone(d);save();go('acuan/editor/'+d.id);}
function persistDraft(){if(!draft)return;draft.updated=new Date().toISOString();const index=db.drafts.findIndex(d=>d.id===draft.id);if(index>=0)db.drafts[index]=clone(draft);else db.drafts.push(clone(draft));save();}
function fieldModal(index){if(!draft)return;const f=index==='new'?{name:'',type:'text',column:true,required:'always',values:[],zero:true,unique:false,format:'DD-MM-YYYY'}:draft.fields[Number(index)];if(!f)return;
 modal(index==='new'?'Tambah Field':'Ubah Field','Aturan berlaku pada kolom dengan nama yang sama.',`<form id="field-form" data-index="${index}"><div class="form-grid">${field('NAMA FIELD',input('name',f.name,'Sesuai nama kolom Excel','text','required'))}${field('TIPE DATA',select('type',f.type,Object.entries(types)))}${field('KEBERADAAN KOLOM',select('column',String(f.column),[['true','Kolom wajib tersedia'],['false','Kolom opsional']]))}${field('KEWAJIBAN ISI',select('required',f.required,[['always','Wajib diisi'],['never','Opsional'],['conditional','Wajib jika kondisi terpenuhi']]))}<div class="span2 form-grid" id="condition-fields" ${f.required==='conditional'?'':'hidden'}>${field('FIELD PENENTU',select('conditionField',f.conditionField||'',[['','Pilih field'],...draft.fields.filter(x=>x.name!==f.name).map(x=>[x.name,x.name])]))}${field('NILAI KONDISI',input('conditionValue',f.conditionValue||'','Contoh: DITARIK'))}</div>${field('DAFTAR NILAI YANG DIIZINKAN',`<textarea name="values" rows="2" placeholder="Contoh: OPERASI, DITARIK">${esc((f.values||[]).join(', '))}</textarea><small>Pisahkan dengan koma. Kosongkan jika tidak dibatasi.</small>`,'span2')}<div class="span2 form-grid" id="numeric-fields" ${['integer','decimal'].includes(f.type)?'':'hidden'}>${field('NILAI MINIMUM',input('min',f.min??'','Tidak dibatasi','number','step="any"'))}${field('NILAI MAKSIMUM',input('max',f.max??'','Tidak dibatasi','number','step="any"'))}<label class="check span2"><input type="checkbox" name="zero" ${f.zero?'checked':''}>Izinkan nilai nol</label></div><div id="date-fields" class="span2" ${f.type==='date'?'':'hidden'}>${field('FORMAT TANGGAL',select('format',f.format||'DD-MM-YYYY',[['DD-MM-YYYY','DD-MM-YYYY (09-05-2024)'],['YYYY-MM-DD','YYYY-MM-DD (2024-05-09)']]))}</div><label class="check span2"><input type="checkbox" name="unique" ${f.unique?'checked':''}>Nilai harus unik pada seluruh baris</label></div><div id="field-errors" class="inline-error"></div></form>`,btn('Batal','close')+'<button class="btn primary" type="submit" form="field-form">Simpan Field</button>',true);
}
function previewPublish(){draft.validated=true;const errs=validateFields(draft.name,draft.fields);persistDraft();render();if(errs.length){toast('Perbaiki konfigurasi yang ditandai sebelum menerbitkan.');return;}const next=draft.family?Math.max(...db.refs.filter(r=>r.family===draft.family).map(r=>r.version))+1:1;
 modal('Pratinjau Acuan',`${draft.name} · ${draft.fields.length} field · Versi ${next}`,`<div class="notice green mb16">Konfigurasi valid. Pastikan field dan aturan sudah sesuai kebutuhan Anda.</div><div class="table-wrap"><table><thead><tr><th>FIELD</th><th>TIPE DATA</th><th>WAJIB KOLOM</th><th>WAJIB ISI</th><th>ATURAN</th></tr></thead><tbody>${referenceRows(draft.fields,false).join('')}</tbody></table></div><p class="muted small mt16">Setelah terbit, versi ini tersedia untuk seluruh pengguna. Pemeriksaan terdahulu tetap menggunakan versi acuannya semula.</p>`,btn('Kembali ke Editor','close')+btn('Submit / Terbitkan','publish','','primary'),true);
}
async function pickFile(onFile){const el=document.createElement('input');el.type='file';el.accept='.xlsx';el.onchange=async()=>{if(!el.files[0])return;try{toast('Membaca file Excel…');const book=await readWorkbook(el.files[0]);await onFile(book);}catch(err){toast(err.message||'File belum dapat dibaca.');}};el.click();}
async function importReference(replace=false){await pickFile(async book=>{const data=fieldsFromBook(book);const apply=()=>{if(!replace)createDraft();draft.name=data.name;draft.description=data.description;draft.fields=data.fields;draft.source=`Diimpor dari ${book.name}.`;draft.validated=true;persistDraft();close();render();toast('Isi Excel sudah dimuat. Perbaiki field langsung di editor.');};if(replace)confirmAction('Timpa isi draf?',`Seluruh field pada draf ini akan diganti dengan isi ${esc(book.name)}.`,apply,'Timpa Draf');else apply();});}
function startExam(){if(!setup?.book){toast('Pilih file data terlebih dahulu.');return;}const ref=db.refs.find(r=>r.id===setup.refId);if(!ref){toast('Pilih acuan yang akan digunakan.');return;}const inp=inputFromBook(setup.book,setup.sheet,Number(setup.header));if(!Number.isInteger(Number(setup.header))||setup.header<1||!inp.headers.length||inp.headers.some(empty)){toast('Pilih baris header dengan nama kolom yang terisi.');return;}if(new Set(inp.headers).size!==inp.headers.length){toast('Nama kolom pada header tidak boleh duplikat.');return;}if(!inp.rows.length){toast('Tidak ada baris data di bawah header.');return;}
 const id='P-'+String(Math.max(0,...db.exams.map(e=>Number(e.id.split('-')[1])))+1).padStart(3,'0');const e={id,owner:uid,input:clone(inp),ref:clone(ref),start:new Date().toISOString(),share:'private',recipients:[],origin:setup.origin};setup.running=e;runStart=Date.now();progress=5;go('pemeriksaan/proses/'+id);clearInterval(timer);timer=setInterval(()=>{progress=Math.min(progress+20,95);if($('#progress-fill'))$('#progress-fill').style.width=progress+'%';if($('#elapsed'))$('#elapsed').textContent=`Waktu berjalan: ${Math.floor((Date.now()-runStart)/1000)} detik`;if(Date.now()-runStart>2200){clearInterval(timer);e.result=examine(inp,ref);e.end=new Date().toISOString();db.exams.push(e);log('Menyelesaikan pemeriksaan',id);setup=null;if(uid===e.owner)go('pemeriksaan/hasil/'+id);toast(`${id} selesai dan tersimpan di riwayat.`);}},500);
}
function baModal(id){const e=getExam(id);if(!e)return;modal('Generate Berita Acara',`${id} · Pilih format dokumen yang akan diunduh.`,`<div class="format-preview"><h3 class="report-title">BERITA ACARA HASIL PEMERIKSAAN DATA</h3><dl class="definition"><dt>Pemeriksa</dt><dd>${esc(user(e.owner).name)}</dd><dt>Data sumber</dt><dd>${esc(e.input.name)}</dd><dt>Acuan</dt><dd>${esc(e.ref.name)} · versi ${e.ref.version}</dd><dt>Hasil</dt><dd>${e.result.bad} dari ${e.result.total} baris perlu perbaikan</dd><dt>Selesai</dt><dd>${stamp(e.end)}</dd></dl></div><p class="muted small mt16">Identitas pemeriksa mengikuti pemeriksaan asal. Dokumen langsung diunduh dan tidak disimpan di sistem.</p>`,btn('Unduh DOCX','download-ba',id+'|docx','','download')+btn('Unduh PDF','download-ba',id+'|pdf','primary','download'));}
const actions={
 'close':close,'confirm':()=>{const f=dialogAction;close();f?.();},
 'ref-tab':v=>{ui.refTab=v;ui.refsPage=1;render();},'exam-tab':v=>{ui.examTab=v;ui.examsPage=1;render();},
 'page':v=>{const[k,d]=v.split('|');ui[k+'Page']=Math.max(1,(ui[k+'Page']||1)+Number(d));render();},
 'new-ref':()=>createDraft(),'copy-ref':id=>{createDraft(db.refs.find(r=>r.id===id));toast('Acuan disalin sebagai draf baru.');},
 'modify-ref':id=>{const ref=db.refs.find(r=>r.id===id&&r.owner===uid);if(ref)createDraft(ref,true);},
 'show-copy':()=>{$('#copy-list')?.scrollIntoView({behavior:'smooth',block:'center'});$('#copy-list input')?.focus();},
 'import-ref':()=>importReference(),'reimport-ref':()=>importReference(true),
 'edit-field':fieldModal,'delete-field':i=>confirmAction('Hapus field?',`Field <b>${esc(draft.fields[i].name)}</b> akan dihapus dari draf.`,()=>{draft.fields.splice(Number(i),1);draft.validated=false;persistDraft();render();},'Hapus Field',true),
 'save-draft':()=>{persistDraft();toast('Draf berhasil disimpan.');},'validate-draft':()=>{draft.validated=true;persistDraft();render();toast(validateFields(draft.name,draft.fields).length?'Ada konfigurasi yang perlu diperbaiki.':'Konfigurasi valid. Acuan siap ditinjau.');},'preview-publish':previewPublish,
 'publish':()=>{const errors=validateFields(draft.name,draft.fields);if(errors.length){close();render();return;}const ref={id:'ref-'+Date.now(),family:draft.family||'family-'+Date.now(),name:draft.name.trim(),description:draft.description,fields:clone(draft.fields),owner:uid,version:draft.family?Math.max(...db.refs.filter(r=>r.family===draft.family).map(r=>r.version))+1:1,published:new Date().toISOString()};db.refs.push(ref);db.drafts=db.drafts.filter(d=>d.id!==draft.id);log('Menerbitkan acuan',ref.name+' v'+ref.version);draft=null;close();go('acuan/lihat/'+ref.id);toast('Acuan berhasil diterbitkan.');},
 'delete-draft':id=>confirmAction('Hapus draf?','Draf yang belum diterbitkan ini akan dihapus.',()=>{db.drafts=db.drafts.filter(d=>d.id!==id||d.owner!==uid);save();render();},'Hapus Draf',true),
 'template':async()=>{download(await workbookBlob(referenceSheets({name:'',description:'',fields:[]})),'Template_Acuan.xlsx');toast('Template Excel diunduh.');},
 'download-ref':async id=>{const r=db.refs.find(r=>r.id===id);download(await workbookBlob(referenceSheets(r)),`${r.name.replace(/[^a-z0-9]/gi,'_')}_v${r.version}.xlsx`);},
 'download-sample':async()=>download(await workbookBlob(sampleBook.sheets),sampleBook.name),
 'import-data':()=>pickFile(book=>{setup??=freshSetup();setup.book=book;setup.sheet=book.sheets[0].name;setup.header=1;render();toast('File data siap ditinjau.');}),
 'use-sample':()=>{setup.book=clone(sampleBook);setup.sheet='Aset';setup.header=1;render();},
 'setup-ref':id=>{const ref=db.refs.find(r=>r.id===id);modal(esc(ref.name),`Versi ${ref.version} · ${ref.fields.length} field`,`<div class="table-wrap"><table><thead><tr><th>FIELD</th><th>TIPE DATA</th><th>WAJIB KOLOM</th><th>WAJIB ISI</th><th>ATURAN</th></tr></thead><tbody>${referenceRows(ref.fields).join('')}</tbody></table></div>`,btn('Tutup','close'),true);},
 'start-exam':startExam,'clear-filters':()=>{['dateFrom','dateTo','examRef','examResult','examSearch'].forEach(k=>ui[k]='');render();},
 'group-history':id=>{const group=filteredGroups().find(g=>g.some(e=>e.id===id));if(!group)return;modal('Riwayat pemeriksaan identik','Input dan versi acuan sama. Setiap hasil tetap tersimpan.',`<div class="timeline">${group.map(e=>`<div class="timeline-item"><span class="avatar">${user(e.owner).short.slice(0,2).toUpperCase()}</span><div class="grow"><b>${e.id}</b><p class="muted small">${user(e.owner).name} · ${stamp(e.end)}</p></div>${btn('Lihat Hasil','open-result',e.id,'small')}</div>`).join('')}</div>`,btn('Tutup','close'));},
 'open-result':id=>{close();go('pemeriksaan/hasil/'+id);},
 'chart-page':d=>{const e=getExam(route()[2]),n=new Set(e.result.findings.map(f=>f.field)).size;ui.chartPage=Math.min(Math.ceil(n/5),Math.max(1,(ui.chartPage||1)+Number(d)));render();},
 'pending':id=>{const e=getExam(id);modal('Kondisi belum dapat dinilai','Lengkapi atau perbaiki field penentu pada file sumber.',`<div class="table-wrap"><table><thead><tr><th>BARIS</th><th>FIELD</th><th>FIELD PENENTU</th></tr></thead><tbody>${e.result.pending.map(p=>`<tr><td>${p.row}</td><td>${esc(p.field)}</td><td>${esc(p.source)}</td></tr>`).join('')}</tbody></table></div>`,btn('Tutup','close'),true);},
 'ba':baModal,'download-ba':async v=>{const[id,format]=v.split('|'),e=getExam(id);download(await createBA(e,user(e.owner).name,format),`BA_${id}.${format}`);log('Mengunduh BA',id);toast('Berita acara diunduh.');},
 'download-data':async id=>{const e=getExam(id);const b=e.input.book;download(b.originalBase64?new Blob([Uint8Array.from(atob(b.originalBase64),c=>c.charCodeAt(0))],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}):await workbookBlob(b.sheets),e.input.name);log('Mengunduh data',id);},
 'report':async id=>{const e=getExam(id),r=e.result;download(await workbookBlob([{name:'Ringkasan',rows:[['Indikator','Nilai'],['ID Pemeriksaan',e.id],['Pemeriksa',user(e.owner).name],['Acuan',e.ref.name+' v'+e.ref.version],['Baris diperiksa',r.total],['Baris perlu perbaikan',r.bad],['Baris memenuhi aturan',r.good],['Isian wajib terisi',r.filled],['Jumlah isian wajib',r.required],['Durasi',duration(e)]]},{name:'Temuan',rows:[['Baris Excel','Field','Nilai File','Aturan / Alasan'],...r.findings.map(f=>[f.row,f.field,f.value,f.reason])]},{name:'Kondisi Belum Dinilai',rows:[['Baris Excel','Field','Field Penentu'],...r.pending.map(p=>[p.row,p.field,p.source])]}]),`Laporan_${id}.xlsx`);log('Mengunduh laporan',id);toast('Laporan Excel diunduh.');},
 'new-account':()=>modal('Tambah Pengguna','Akun dibuat oleh administrator.',`<form id="account-form" class="stack">${field('NAMA LENGKAP',input('name','','Nama untuk BA dan log','text','required'))}${field('USERNAME',input('username','','Huruf, angka, titik, atau garis bawah','text','required pattern="[a-zA-Z0-9_.]+"'))}${field('PASSWORD AWAL',input('password','','Minimal 6 karakter','password','required minlength="6"'))}<div id="account-error" class="inline-error"></div></form>`,btn('Batal','close')+'<button class="btn primary" form="account-form">Buat Akun</button>'),
 'reset-password':id=>modal('Reset Password',`Akun: ${esc(user(id).name)}`,`<form id="password-form" data-id="${id}">${field('PASSWORD BARU',input('password','','Minimal 6 karakter','password','required minlength="6"'))}<p class="muted small mt16">Gunakan password khusus demo pada prototipe ini.</p></form>`,btn('Batal','close')+'<button class="btn primary" form="password-form">Simpan Password</button>'),
 'toggle-user':id=>{if(me().role!=='admin')return;const u=user(id);confirmAction(u.active?'Nonaktifkan akun?':'Aktifkan akun?',`Ubah akses masuk akun ${esc(u.name)}?`,()=>{u.active=!u.active;log(u.active?'Mengaktifkan akun':'Menonaktifkan akun',u.username);render();});},
 'logout':()=>{uid='';sessionStorage.setItem('demo-user','');render();},
 'demo-guide':()=>modal('Panduan Demo','Coba alur dari acuan sampai hasil pemeriksaan.',`<div class="stack"><div><h3>1. Buat atau salin acuan</h3><p class="muted small">Buka Acuan → Buat Acuan. Isi field, validasi, lalu terbitkan.</p></div><div><h3>2. Jalankan pemeriksaan</h3><p class="muted small">Buka Pemeriksaan → Pemeriksaan Baru → Gunakan Data Contoh. Pilih Data Aset versi 1, lalu mulai.</p></div><div><h3>3. Telusuri hasil</h3><p class="muted small">Lihat temuan, pratinjau data dan acuan, unduh laporan atau BA.</p></div><div><h3>4. Coba berbagi akses</h3><p class="muted small">Bagikan ke Budi, kemudian ganti pengguna melalui pilihan di kiri bawah.</p></div><div class="notice">Ini simulasi dalam browser. Data tersimpan pada perangkat ini; belum ada server, autentikasi nyata, atau berbagi antarperangkat. Gunakan data contoh.</div></div>`,btn('Reset Data Demo','reset-demo','','danger')+btn('Mulai Mencoba','close','','primary')),
 'reset-demo':()=>confirmAction('Reset data demo?','Perubahan acuan, akun, dan pemeriksaan pada browser ini akan dihapus dan dikembalikan ke contoh awal.',()=>{clearInterval(timer);db=seed();uid='rina';ui={};draft=null;setup=null;save();sessionStorage.setItem('demo-user',uid);go('acuan');render();toast('Data demo dikembalikan ke kondisi awal.');},'Reset Demo',true)
};
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();try{await actions[el.dataset.action]?.(el.dataset.arg);}catch(error){console.error(error);toast('Tindakan belum berhasil. Silakan coba lagi.');}});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.draft){draft[el.dataset.draft]=el.value;draft.validated=false;persistDraft();}if(el.dataset.search){const key=el.dataset.search,pos=el.selectionStart;ui[key]=el.value;for(const k of Object.keys(ui))if(k.endsWith('Page'))ui[k]=1;render();const next=document.querySelector(`[data-search="${key}"]`);next?.focus();next?.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='demo-user'){uid=el.value;sessionStorage.setItem('demo-user',uid);draft=null;setup=null;ui={};go('acuan');render();}
 if(el.dataset.filter){ui[el.dataset.filter]=el.value;ui.examsPage=1;render();}if(el.dataset.pageSize){ui[el.dataset.pageSize+'Size']=Number(el.value);ui[el.dataset.pageSize+'Page']=1;render();}if(el.hasAttribute('data-version'))go('acuan/lihat/'+el.value);
 if(el.dataset.setup){setup[el.dataset.setup]=el.value;ui.setupPreviewPage=1;render();}
 if(el.name==='shareScope')$('#recipient-list').hidden=el.value!=='selected';
 if(el.closest('#field-form')){if(el.name==='required')$('#condition-fields').hidden=el.value!=='conditional';if(el.name==='type'){$('#numeric-fields').hidden=!['integer','decimal'].includes(el.value);$('#date-fields').hidden=el.value!=='date';}}
});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,fd=new FormData(form);
 if(form.id==='field-form'){const f={name:String(fd.get('name')).trim(),type:fd.get('type'),column:fd.get('column')==='true',required:fd.get('required'),conditionField:fd.get('conditionField'),conditionValue:String(fd.get('conditionValue')||'').trim(),values:String(fd.get('values')||'').split(',').map(v=>v.trim()).filter(Boolean),zero:['integer','decimal'].includes(fd.get('type'))?fd.has('zero'):true,min:['integer','decimal'].includes(fd.get('type'))?fd.get('min'):'',max:['integer','decimal'].includes(fd.get('type'))?fd.get('max'):'',unique:fd.has('unique'),format:fd.get('format')};const idx=form.dataset.index;const fields=clone(draft.fields);if(idx==='new')fields.push(f);else fields[Number(idx)]=f;const errors=validateFields(draft.name||'Draf',fields).filter(e=>e.startsWith(f.name+':'));if(errors.length){$('#field-errors').textContent=errors.join(' ');return;}draft.fields=fields;draft.validated=false;persistDraft();close();render();toast('Field dan aturan disimpan.');}
 if(form.id==='share-form'){const e=getExam(form.dataset.id);if(!e||e.owner!==uid)return;const recipients=fd.getAll('recipient');if(fd.get('shareScope')==='selected'&&!recipients.length){toast('Pilih sedikitnya satu pengguna.');return;}e.share=fd.get('shareScope');e.recipients=e.share==='selected'?recipients:[];log('Mengubah akses pemeriksaan',e.id);go('pemeriksaan/hasil/'+e.id);toast('Pengaturan akses disimpan.');}
 if(form.id==='repeat-form'){const e=getExam(form.dataset.id),mode=fd.get('repeatMode');setup={book:['same','ref'].includes(mode)?clone(e.input.book):null,sheet:e.input.sheet,header:e.input.header,refId:['same','file'].includes(mode)?e.ref.id:'',origin:e.id};go('pemeriksaan/baru');}
 if(form.id==='account-form'&&me().role==='admin'){const username=String(fd.get('username')).trim().toLowerCase();if(db.users.some(u=>u.username.toLowerCase()===username)){$('#account-error').textContent='Username sudah digunakan.';return;}db.users.push({id:'user-'+Date.now(),name:String(fd.get('name')).trim(),short:String(fd.get('name')).trim().split(' ')[0],username,password:fd.get('password'),role:'user',active:true});log('Membuat akun',username);close();render();toast('Akun pengguna dibuat.');}
 if(form.id==='password-form'&&me().role==='admin'){user(form.dataset.id).password=fd.get('password');log('Mereset password',user(form.dataset.id).username);close();toast('Password demo diperbarui.');}
 if(form.id==='login-form'){const u=db.users.find(u=>u.username===String(fd.get('username')).trim().toLowerCase()&&u.active&&(u.password||'demo123')===fd.get('password'));if(!u){$('#login-error').textContent='Username atau password salah, atau akun tidak aktif.';return;}uid=u.id;sessionStorage.setItem('demo-user',uid);ui={};go('acuan');render();}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#overlay').children.length)close();if(event.key==='Tab'&&$('.modal')){const els=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{close();ui.findingSearch='';ui.dataSearch='';ui.fieldSearch='';ui.chartPage=1;render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',event=>{if(setup?.running){event.preventDefault();event.returnValue='';}});
render();
